using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
public static class RuinsTrimReview{
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static Color32[] Shot(Camera c,Vector3 from,Vector3 at,string f){c.transform.position=from;c.transform.LookAt(at);var rt=new RenderTexture(1200,900,24);c.targetTexture=rt;for(int i=0;i<3;i++)c.Render();var old=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(1200,900,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1200,900),0,0);t.Apply();File.WriteAllBytes(f,t.EncodeToPNG());var pixels=t.GetPixels32();RenderTexture.active=old;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(t);return pixels;}
 public static void Run(){const string ev="Evidence/Target36Trim";Directory.CreateDirectory(ev);try{
 EditorSceneManager.OpenScene("Assets/RuinsTarget36Output/Room.unity");var root=GameObject.Find("ruins_1").transform.parent.gameObject;var c=UnityEngine.Object.FindAnyObjectByType<Camera>();var sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).Single(x=>x.type==LightType.Directional);sun.transform.rotation=Quaternion.Euler(38,-28,0);RenderSettings.ambientLight=Color.gray*.65f;c.orthographic=false;c.backgroundColor=new Color(.075f,.085f,.1f);
 var pixels=Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/room.png");UnityEngine.Object.DestroyImmediate(root);root=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget36Output/Structures/Ruins.prefab"));Check(pixels.SequenceEqual(Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/prefab.png")),"Prefab reload pixels");
 var saved="Assets/RuinsTarget36Output/TrimPersistence.unity";EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),saved);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);EditorSceneManager.OpenScene(saved);root=GameObject.Find("ruins_1").transform.parent.gameObject;c=UnityEngine.Object.FindAnyObjectByType<Camera>();sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).Single(x=>x.type==LightType.Directional);Check(pixels.SequenceEqual(Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/scene.png")),"Scene reload pixels");
 var old=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget34Output/Structures/Ruins.prefab"));foreach(Transform t in root.transform){var b=old.transform.Find(t.name);if((t.name=="ruins_19"||t.name=="ruins_17")||b==null||!t.TryGetComponent<MeshFilter>(out var filter))continue;var prior=b.GetComponent<MeshFilter>().sharedMesh;Check(filter.sharedMesh.vertices.SequenceEqual(prior.vertices)&&filter.sharedMesh.normals.SequenceEqual(prior.normals)&&filter.sharedMesh.triangles.SequenceEqual(prior.triangles),"Geometry changed "+t.name);Check(t.GetComponent<MeshCollider>().sharedMesh==filter.sharedMesh,"Collider identity "+t.name);}
 foreach(var obj in new[]{root,old})foreach(int id in new[]{17,19,38,39,40,41,42,43}){var t=obj.transform.Find("ruins_"+id);if(t!=null)t.gameObject.SetActive(false);};root.SetActive(false);var before=Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/unchanged-before.png");old.SetActive(false);root.SetActive(true);Check(before.SequenceEqual(Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/unchanged-after.png")),"Other part appearance changed");
 foreach(var obj in new[]{root,old})foreach(Transform child in obj.transform)child.gameObject.SetActive(new[]{"ruins_17","ruins_18","ruins_19","ruins_38","ruins_39","ruins_40","ruins_41","ruins_42","ruins_43"}.Contains(child.name));var center=root.transform.Find("ruins_17").GetComponent<MeshRenderer>().bounds.center;
 foreach(var view in new[]{"normal","close","opposite"}){sun.transform.rotation=view=="opposite"?Quaternion.Euler(27,130,0):Quaternion.Euler(38,-28,0);c.orthographic=true;c.orthographicSize=view=="normal"?4.4f:2.9f;var pos=center+new Vector3(-7,5,8);root.SetActive(false);old.SetActive(true);Shot(c,pos,center,ev+"/before-"+view+".png");old.SetActive(false);root.SetActive(true);Shot(c,pos,center,ev+"/after-"+view+".png");}
 sun.transform.rotation=Quaternion.Euler(38,-28,0);
 foreach(int id in new[]{38,42}){foreach(Transform t in root.transform)t.gameObject.SetActive(t.name=="ruins_"+id);var centerPart=root.transform.Find("ruins_"+id).GetComponent<MeshRenderer>().bounds.center;c.orthographicSize=.85f;Shot(c,centerPart+new Vector3(-4,3,5),centerPart,ev+"/part-"+id+".png");}
 foreach(Transform t in root.transform)t.gameObject.SetActive(true);Physics.SyncTransforms();
 int jointRays=0;foreach(var j in new[]{new[]{19f,38f,-1.5f,2.5f,0f,1f},new[]{38f,40f,-1f,3f,1f,0f},new[]{40f,39f,1f,3f,1f,0f},new[]{39f,41f,1.5f,2.5f,0f,-1f},new[]{42f,19f,-1.5f,1.5f,0f,1f},new[]{43f,41f,1.5f,1.5f,0f,1f}}){var a=root.transform.Find("ruins_"+(int)j[0]).GetComponent<MeshCollider>();var b=root.transform.Find("ruins_"+(int)j[1]).GetComponent<MeshCollider>();var d=new Vector3(j[4],0,-j[5]);var point=new Vector3(j[2],5.35f,-j[3]);foreach(float dy in new[]{-.035f,0,.035f}){var at=point+Vector3.up*dy;RaycastHit ha=default,hb=default;Check(a.Raycast(new Ray(at+d*.08f,-d),out ha,.16f)&&b.Raycast(new Ray(at-d*.08f,d),out hb,.16f),"Joint surfaces "+j[0]+"/"+j[1]);Check(Vector3.Distance(ha.point,hb.point)<.002f,"Joint gap "+j[0]+"/"+j[1]);jointRays+=2;}}

 foreach(int id in new[]{38,42}){var template=root.transform.Find("ruins_"+id).gameObject;foreach(int n in new[]{9,225}){var clones=Enumerable.Range(0,n).Select(i=>{var o=UnityEngine.Object.Instantiate(template);o.transform.position=new Vector3(100+i*6,0,100);return o;}).ToArray();Check(clones.Select(o=>o.GetComponent<MeshFilter>().sharedMesh).Distinct().Count()==1&&clones.Select(o=>o.GetComponent<MeshRenderer>().sharedMaterial).Distinct().Count()==1,"Shared references");foreach(var o in clones)UnityEngine.Object.DestroyImmediate(o);}}
 Check(!ShaderUtil.ShaderHasError(Shader.Find("MapRuins/AgedLimestone")),"Shader error");File.WriteAllText(ev+"/result.json","{\"pass\":true,\"oldGeometryAndCollidersUnchangedExceptEdgeLayoutAndPlatformBearing\":true,\"prefabScenePixelDelta\":0,\"otherPartsPixelDelta\":0,\"shared9And225\":true,\"jointRays\":36,\"GPUmeasured\":false}");EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(ev+"/failure.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
